<?php
namespace App\Http\Controllers;
use App\Models\{About,CompanyContent,ContactItem,Destination,Faq,GalleryAlbum,GalleryMedia,NavigationItem,Page,PickupPoint,Review,Setting,Social,Tour,TourCategory,VisaService};use Illuminate\Contracts\View\View;
class FrontPageController extends Controller{
 public function show(string $pageKey):View{
  // A page switched off in admin is gone for visitors; a page with no CMS row yet still renders its template.
  $cmsPage=Page::where('key',$pageKey)->with(['sections'=>fn($q)=>$q->with('translations')])->first();
  abort_if($cmsPage&&!$cmsPage->is_active,404);
  if(!$cmsPage){$cmsPage=new Page(['key'=>$pageKey,'template'=>$pageKey]);$cmsPage->translateOrNew('en')->title='DreamTour';$cmsPage->setRelation('sections',collect());}
  // Inactive sections are hidden outright, not replaced by the template's fallback wording.
  $hiddenSections=$cmsPage->sections->where('is_active',false)->pluck('key');
  $showSection=fn(string ...$keys)=>collect($keys)->contains(fn($key)=>!$hiddenSections->contains($key));
  return view('front.pages.'.$cmsPage->template,array_merge(['cmsPage'=>$cmsPage,'sections'=>$cmsPage->sections->where('is_active',true)->keyBy('key'),'showSection'=>$showSection,'about'=>About::with('translations')->where('key','main')->first(),'aboutBlocks'=>About::with('translations')->whereIn('key',['vision','mission','founder'])->get()->keyBy('key'),'frontendData'=>$this->frontendData()],$this->globals()));}
 private function globals():array{return ['siteSettings'=>Setting::pluck('value','key'),'headerNavigation'=>NavigationItem::where('location','header')->whereNull('parent_id')->where('is_active',true)->with(['translations','children'=>fn($q)=>$q->where('is_active',true)->with('translations')])->orderBy('sort_order')->get(),'footerNavigation'=>NavigationItem::whereIn('location',['footer_company','footer_support','footer_legal'])->where('is_active',true)->with('translations')->orderBy('sort_order')->get()->groupBy('location'),'contactItems'=>ContactItem::active()->ordered()->with('translations')->get(),'socials'=>Social::active()->ordered()->get()];}
 private function frontendData():array{
  $tourModels=Tour::where('status','published')->with(['filterOptions.filter','translations','destination.translations','destination.parent.translations','categories.translations','transportations.translations','cruiseDetail','departures'=>fn($q)=>$q->visible()->with('prices')->orderBy('departs_at')])->withAvg(['reviews'=>fn($q)=>$q->published()],'rating')->withCount(['reviews'=>fn($q)=>$q->published()])->orderBy('sort_order')->get();$tours=$tourModels->map(fn($t)=>$this->tourPayload($t));
  // Destination and custom-category links open the listing page that actually holds those tours.
  $pageFor=function(callable $match)use($tours){$listing=$tours->filter($match)->flatMap(fn($t)=>$t['listings'])->countBy()->sortDesc()->keys()->first();return match($listing){'multi-day'=>'/multi-day-tours','international'=>'/international-tours','cruises'=>'/cruises','private'=>'/private-tours',default=>'/one-day-tours'};};
  $categories=TourCategory::where('is_active',true)->withCount(['tours'=>fn($q)=>$q->where('status','published')])->with('translations')->orderBy('sort_order')->get()->map(function($category)use($pageFor){
   $slug=$category->slug;
   $href=match($slug){'one-day'=>'/one-day-tours','multi-day'=>'/multi-day-tours','international'=>'/international-tours','cruises'=>'/cruises','private'=>'/private-tours','visa-support'=>'/visa-support',default=>$pageFor(fn($t)=>$t['categoryIds']->contains($category->id)).'?category='.$category->id};
   return ['id'=>$category->id,'name'=>$category->name,'slug'=>$slug,'description'=>$category->description,'image'=>$category->image,'tourCount'=>$category->tours_count,'href'=>$href];
  });
  $destinations=Destination::where('is_active',true)->withCount(['tours'=>fn($q)=>$q->where('status','published')])->with(['translations','parent.translations'])->orderBy('sort_order')->get()->map(fn($d)=>['id'=>$d->id,'slug'=>$d->slug,'name'=>$d->name,'region'=>$d->parent?->name?:$d->name,'description'=>$d->description,'image'=>$d->image,'tourCount'=>$d->tours_count,'href'=>$pageFor(fn($t)=>$t['destinationId']===$d->id||$t['countryId']===$d->id).'?destination='.$d->id]);
  $company=CompanyContent::where('is_active',true)->with('translations')->orderBy('sort_order')->get()->groupBy('type');
  // Pinned team members (the founder / CEO) always come first; the rest keep their admin order.
  $company->put('team',collect($company->get('team',[]))->sortBy([['pinned','desc'],['sort_order','asc']])->values());$reviews=Review::published()->with(['translations','tour.translations'])->orderBy('order')->latest()->get()->map(fn($r)=>['name'=>$r->name,'role'=>$r->tour?->name?:$r->position,'text'=>$r->content,'rating'=>$r->rating,'photo'=>$r->image,'tourHref'=>$r->tour?'/tours/'.$r->tour->slug:null]);$approvedReviews=Review::published();
  $gallery=GalleryMedia::where(fn($q)=>$q->whereNull('gallery_album_id')->orWhereHas('album',fn($a)=>$a->where('is_active',true)))->with(['translations','album.translations'])->orderBy('sort_order')->get()->map(fn($m)=>['id'=>$m->id,'src'=>$m->path,'thumb'=>$m->thumbnail?:$m->path,'alt'=>$m->alt_text,'caption'=>$m->caption,'album'=>$m->album?->title,'type'=>$m->type]);
  $albums=GalleryAlbum::where('is_active',true)->with(['translations','category.translations','destination.translations','tour.translations','media.translations'])->get()->map(fn($a)=>['id'=>$a->id,'tour'=>$a->tour?->name?:$a->title,'tourSlug'=>$a->tour?->slug,'country'=>$a->destination?->name,'date'=>$a->tour_date?->format('Y-m-d'),'year'=>$a->tour_date?->year,'month'=>$a->tour_date?->format('F'),'category'=>$a->category?->name,'cover'=>$a->cover_image,'photos'=>$a->media->map(fn($m)=>['src'=>$m->path,'thumb'=>$m->thumbnail?:$m->path,'alt'=>$m->alt_text,'caption'=>$m->caption])->values()]);
  $visa=VisaService::where('is_active',true)->with(['translations','destination.parent.translations'])->orderBy('sort_order')->get();
  $faqItems=Faq::where('is_active',true)->with('translations')->orderBy('order')->get()->groupBy('group');
  $faqs=collect($faqItems->get('trip',[]))->map(fn($f)=>['q'=>$f->question,'a'=>$f->answer])->values();
  $visaFaqs=collect($faqItems->get('visa',[]))->map(fn($f)=>['q'=>$f->question,'a'=>$f->answer])->values();
  $tourFilters=\App\Models\TourFilter::where('is_active',true)->with(['options'=>fn($q)=>$q->where('is_active',true)])->orderBy('sort_order')->get()->map(fn($f)=>['id'=>$f->id,'name'=>$f->name,'listing'=>$f->listing,'options'=>$f->options->map(fn($o)=>['id'=>$o->id,'name'=>$o->name])->values()])->values();
  return ['tourFilters'=>$tourFilters,'tours'=>$tours,'destinations'=>$destinations,'cruises'=>$tourModels->where('is_cruise',true)->map(fn($t)=>$this->cruisePayload($t))->values(),'categories'=>$categories,'advantages'=>$this->company($company,'advantage',fn($x)=>['title'=>$x->title,'description'=>$x->description,'image'=>$x->image,'url'=>$x->url]),'about'=>['stats'=>$this->company($company,'statistic',fn($x)=>['value'=>$x->value,'label'=>$x->title]),'partners'=>$this->company($company,'partner',fn($x)=>['name'=>$x->title,'full'=>$x->subtitle,'note'=>$x->description])],'team'=>$this->company($company,'team',fn($x)=>['id'=>$x->id,'name'=>$x->title,'role'=>$x->subtitle,'photo'=>$x->image,'bio'=>$x->description,'socials'=>[]]),'privateTours'=>['places'=>$this->company($company,'private_place',fn($x)=>['name'=>$x->title,'tagline'=>$x->subtitle,'description'=>$x->description,'image'=>$x->image,'url'=>$x->url]),'steps'=>$this->company($company,'private_step',fn($x)=>['title'=>$x->title,'description'=>$x->description]),'ideas'=>$tours->filter(fn($x)=>in_array('private',$x['listings'],true))->map(fn($x)=>['id'=>$x['id'],'title'=>$x['name'],'duration'=>$x['duration'],'image'=>$x['image'],'tags'=>[],'summary'=>$x['description']])->values()],'reviewsSummary'=>['rating'=>round((float)(clone $approvedReviews)->avg('rating'),1),'count'=>(clone $approvedReviews)->count()],'heroSlides'=>$this->company($company,'hero_slide',fn($x)=>['image'=>$x->image,'place'=>$x->title,'caption'=>$x->subtitle,'alt'=>$x->description,'url'=>$x->url]),'reviews'=>$reviews,'gallery'=>$gallery,'galleryAlbums'=>$albums,'faqs'=>$faqs,'visa'=>['steps'=>$this->company($company,'visa_step',fn($x)=>['title'=>$x->title,'description'=>$x->description]),'services'=>$visa->map(fn($v)=>['country'=>$v->country?:($v->destination?->name?:$v->name),'service'=>($v->country||$v->destination)?$v->name:null,'region'=>$v->destination?->parent?->name,'summary'=>$v->description,'processing'=>$v->processing_time,'fee'=>(float)($v->price??0),'feeLabel'=>$v->price!==null?money($v->price,$v->currency):null,'thirdPartyFee'=>$v->third_party_fee!==null?money($v->third_party_fee,$v->currency):null,'thirdPartyNote'=>$v->third_party_fee_note,'documents'=>$this->lines($v->required_documents),'disclaimer'=>$v->disclaimer]),'documents'=>$visa->flatMap(fn($v)=>$this->lines($v->required_documents))->unique()->values()->map(fn($d)=>['name'=>$d,'detail'=>''])->values(),'disclaimer'=>$visa->pluck('disclaimer')->filter()->first(),'faqs'=>$visaFaqs],'pickupPoints'=>PickupPoint::where('is_active',true)->with('translations')->orderBy('sort_order')->get()->map(fn($p)=>['id'=>$p->id,'name'=>$p->name,'area'=>$p->address])];
 }
 private function tourPayload(Tour $t):array
 {
  $d=$t->departures->first(fn($x)=>$x->is_bookable)??$t->departures->first();$transport=$t->transportations->first();$destination=$t->destination;$country=$destination?->parent?->name?:$destination?->name;$type=$t->is_cruise?'cruise':($t->is_private?'private':($t->duration_days>1?'multi-day':'one-day'));$slugs=$t->categories->pluck('slug')->all();$listings=array_values(array_intersect(['one-day','multi-day','international','cruises','private'],$slugs))?:[$type==='cruise'?'cruises':$type];
  // Only active options of active filter groups count on the listings.
  $filterOptionIds=$t->filterOptions->filter(fn($o)=>$o->is_active&&$o->filter?->is_active)->pluck('id')->values();
  return ['id'=>$t->id,'filterOptionIds'=>$filterOptionIds,'slug'=>$t->slug,'href'=>'/tours/'.$t->slug,'name'=>$t->name,'image'=>$t->main_image,'date'=>$d?->departs_at?->format('M j, Y'),'dateValue'=>$d?->departs_at?->format('Y-m-d'),'returnDate'=>$d?->returns_at?->format('Y-m-d'),'duration'=>$t->duration_days===1?'Full Day':$t->duration_days.' Days / '.$t->duration_nights.' Nights','days'=>$t->duration_days,'destination'=>$destination?->name,'country'=>$country,'region'=>$country,'categories'=>$t->categories->pluck('name')->values(),'description'=>$t->short_description,'price'=>$d?$d->from_price:0.0,'currency'=>$d?->currency?:'CAD','roomPricing'=>(bool)$d?->has_room_pricing,'departureCount'=>$t->departures->count(),'dates'=>$t->departures->map(fn($x)=>$x->departs_at->format('Y-m-d'))->values(),'rating'=>$t->reviews_count?round((float)$t->reviews_avg_rating,1):null,'reviewCount'=>$t->reviews_count,'destinationId'=>$destination?->id,'countryId'=>$destination?->parent_id?:$destination?->id,'categoryIds'=>$t->categories->pluck('id')->values(),'listings'=>$listings,'previousPrice'=>$d?->old_price?(float)$d->old_price:null,'seatsLeft'=>$d?->available_seats??0,'capacity'=>$d?->capacity??0,'availability'=>$d?->status??'coming_soon','ageRestriction'=>$t->age_restriction,'transport'=>$transport?->name,'vehicle'=>$transport?->type,'label'=>$t->badge?str($t->badge)->replace('_',' ')->title()->toString():null,'type'=>$type,'isPrivate'=>$t->is_private,'isCruise'=>$t->is_cruise,'home'=>$t->show_on_home,'international'=>in_array('international',$listings,true)];
 }
 private function cruisePayload(Tour $t):array{$d=$t->departures->first();$detail=$t->cruiseDetail;return ['id'=>$t->id,'slug'=>$t->slug,'name'=>$t->name,'line'=>$detail?->company,'image'=>$t->main_image,'region'=>$t->destination?->name,'destination'=>$t->destination?->name,'port'=>$detail?->departure_port,'date'=>$d?->departs_at?->format('M j, Y'),'nights'=>$t->duration_nights,'duration'=>$t->duration_nights.' nights','price'=>$d?$d->from_price:0.0,'currency'=>$d?->currency?:'CAD','previousPrice'=>$d?->old_price?(float)$d->old_price:null,'cabinFrom'=>$detail?->cabin_type,'cabinTypes'=>array_values(array_filter(array_map('trim',explode(',',$detail?->cabin_type??'')))),'cabinsLeft'=>$d?->available_seats??0,'documents'=>array_values(array_filter((array)($detail?->documents??[]))),'description'=>$t->short_description,'withTour'=>$t->transportations->contains(fn($transport)=>$transport->type!=='cruise_ship'),'label'=>$t->badge?str($t->badge)->replace('_',' ')->title()->toString():null];}
 private function company($groups,string $key,callable $map){return collect($groups->get($key,[]))->map($map)->values();}
 /** Split an admin textarea into a clean list of lines. @return \Illuminate\Support\Collection<int,string> */
 private function lines(?string $text){return collect(preg_split('/\r\n|\r|\n/',(string)$text))->map(fn($line)=>trim($line))->filter()->values();}
}
